import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

import { Icon } from "@/registry/erbium/ui/icon";
import type { IconProps } from "@/registry/erbium/ui/icon";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarRail,
  SidebarTrigger,
} from "@/registry/erbium/ui/sidebar";

export interface SidebarExampleProps {
  side?: "left" | "right";
  variant?: "sidebar" | "inset";
  collapsible?: "offcanvas" | "icon" | "none";
  defaultOpen?: boolean;
}

const main = [
  { badge: 4, icon: "inbox", label: "Inbox" },
  { current: true, icon: "folder-open", label: "Projects" },
  { icon: "settings-01", label: "Settings" },
] satisfies { badge?: number; current?: boolean; icon: IconProps["name"]; label: string }[];

const projects = [
  { icon: "frame", label: "Design Engineering" },
  { icon: "pie-chart", label: "Sales & Marketing" },
  { icon: "map", label: "Travel" },
] satisfies { icon: IconProps["name"]; label: string }[];

export default function SidebarExample({
  side = "left",
  variant = "sidebar",
  collapsible = "icon",
  defaultOpen = true,
}: SidebarExampleProps) {
  return (
    // The provider fills the viewport by default. Here it fills its container, at least 24rem
    // tall, and the sidebar is positioned inside it instead of against the viewport.
    <SidebarProvider
      key={String(defaultOpen)}
      defaultOpen={defaultOpen}
      className="relative h-full min-h-96 overflow-hidden rounded-lg border contain-layout"
    >
      <Sidebar
        side={side}
        variant={variant}
        collapsible={collapsible}
        // A collapsible sidebar is fixed to the viewport by default; this one stays in the frame.
        className={collapsible === "none" ? undefined : "absolute h-full"}
      >
        <SidebarHeader>
          <SidebarMenu>
            <SidebarMenuItem>
              <SidebarMenuButton tooltip="Acme">
                <Icon name="building-02" />
                <span>Acme</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          </SidebarMenu>
        </SidebarHeader>
        <SidebarContent>
          <SidebarGroup>
            <SidebarGroupContent>
              <SidebarMenu>
                {main.map((item) => (
                  <SidebarMenuItem key={item.label}>
                    <SidebarMenuButton
                      tooltip={item.label}
                      aria-current={"current" in item ? "page" : undefined}
                    >
                      <Icon name={item.icon} />
                      <span>{item.label}</span>
                    </SidebarMenuButton>
                    {"badge" in item && <SidebarMenuBadge>{item.badge}</SidebarMenuBadge>}
                  </SidebarMenuItem>
                ))}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
          <SidebarGroup>
            <SidebarGroupLabel>Projects</SidebarGroupLabel>
            <SidebarGroupContent>
              <SidebarMenu>
                {projects.map((project) => (
                  <SidebarMenuItem key={project.label}>
                    <SidebarMenuButton tooltip={project.label}>
                      <Icon name={project.icon} />
                      <span>{project.label}</span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                ))}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
        <SidebarFooter>
          <span className="truncate px-2 text-control-sm text-muted-foreground">ada@acme.dev</span>
        </SidebarFooter>
        {collapsible !== "none" && <SidebarRail />}
      </Sidebar>
      <SidebarInset>
        <header className="flex h-12 shrink-0 items-center gap-related border-b px-3">
          {collapsible !== "none" && <SidebarTrigger side={side} />}
          <span className="text-control">Projects</span>
        </header>
        <div className="p-6 text-body text-muted-foreground">Three projects are on track.</div>
      </SidebarInset>
    </SidebarProvider>
  );
}

import SidebarExample from "../examples/sidebar-demo";

export default function SidebarOverviewExample() {
  return <SidebarExample />;
}

import SidebarExample from "../examples/sidebar-demo";
import type { SidebarExampleProps } from "../examples/sidebar-demo";

export const defaultProps = {
  collapsible: "icon",
  defaultOpen: true,
  side: "left",
  variant: "sidebar",
} satisfies Required<SidebarExampleProps>;

export default function SidebarPlaygroundExample(
  args: Required<SidebarExampleProps> = defaultProps,
) {
  return <SidebarExample {...args} />;
}
